style.css:
/* Ép toàn bộ web dùng Google Sans */
* {
    font-family: "Google Sans", "Product Sans", Roboto, sans-serif !important;
    -webkit-font-smoothing: antialiased; /* Giúp font mảnh và sắc nét hơn */
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

/* Tinh chỉnh riêng cho tiêu đề để giống UI của Gemini */
h1, h2, h3, h4, b, strong {
    font-weight: 500 !important;
    letter-spacing: -0.02em !important;
}
